package local.phonecommander.observer;
import android.app.*;import android.content.*;import android.os.*;import android.media.*;import android.media.projection.*;import android.hardware.display.*;import android.graphics.*;import android.util.DisplayMetrics;import android.view.WindowManager;import java.io.*;import java.nio.*;
public class CaptureService extends Service {
 private MediaProjection projection;private VirtualDisplay display;private ImageReader reader;private HandlerThread thread;private long last;
 public IBinder onBind(Intent intent){return null;}
 public int onStartCommand(Intent intent,int flags,int id){if(projection!=null)return START_NOT_STICKY;if(intent==null||!Hub.active()){stopSelf();return START_NOT_STICKY;}
  NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("sharing","Phone Commander sharing",NotificationManager.IMPORTANCE_LOW));startForeground(41,new Notification.Builder(this,"sharing").setSmallIcon(android.R.drawable.ic_menu_view).setContentTitle("Phone Commander screen sharing").setContentText("Open Observer to stop sharing and revoke pairing.").setOngoing(true).build());
  MediaProjectionManager manager=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);projection=manager.getMediaProjection(intent.getIntExtra("result",0),intent.getParcelableExtra("projection"));if(projection==null){stopSelf();return START_NOT_STICKY;}
  thread=new HandlerThread("projection-encoder");thread.start();Handler handler=new Handler(thread.getLooper());projection.registerCallback(new MediaProjection.Callback(){public void onStop(){stopSelf();}},handler);
  DisplayMetrics metrics=new DisplayMetrics();((WindowManager)getSystemService(WINDOW_SERVICE)).getDefaultDisplay().getRealMetrics(metrics);Hub.sourceWidth=metrics.widthPixels;Hub.sourceHeight=metrics.heightPixels;int width=Math.min(720,metrics.widthPixels),height=(int)((long)metrics.heightPixels*width/metrics.widthPixels);reader=ImageReader.newInstance(width,height,PixelFormat.RGBA_8888,2);
  reader.setOnImageAvailableListener(source->{try(Image image=source.acquireLatestImage()){if(image==null)return;if(!Hub.active()){stopSelf();return;}long at=System.currentTimeMillis();if(!ObserverService.allowedWindow()){Hub.frame=null;return;}if(at-last<100)return;last=at;Image.Plane plane=image.getPlanes()[0];int padded=width+(plane.getRowStride()-plane.getPixelStride()*width)/plane.getPixelStride();Bitmap raw=Bitmap.createBitmap(padded,height,Bitmap.Config.ARGB_8888);raw.copyPixelsFromBuffer(plane.getBuffer());Bitmap crop=Bitmap.createBitmap(raw,0,0,width,height);ByteArrayOutputStream bytes=new ByteArrayOutputStream();crop.compress(Bitmap.CompressFormat.JPEG,70,bytes);if(bytes.size()<=1048576){Hub.frame=bytes.toByteArray();Hub.frameAt=at;}if(crop!=raw)crop.recycle();raw.recycle();}catch(RuntimeException ignored){}},handler);
  display=projection.createVirtualDisplay("PhoneCommander",width,height,metrics.densityDpi,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,reader.getSurface(),null,handler);handler.postDelayed(()->stopSelf(),600000);return START_NOT_STICKY;
 }
 public void onDestroy(){Hub.stop();if(display!=null)display.release();if(reader!=null)reader.close();if(projection!=null)projection.stop();if(thread!=null)thread.quitSafely();super.onDestroy();}
}